<?php
declare(strict_types=1);
require __DIR__ . '/app/auth.php';
exigirEquipe();
require __DIR__ . '/app/db.php';

$obras = banco()->query('SELECT o.*, (SELECT resumo FROM atualizacoes_obra a WHERE a.obra_id = o.id ORDER BY a.data_atualizacao DESC, a.id DESC LIMIT 1) AS ultimo_resumo FROM obras_acompanhamento o ORDER BY o.atualizado_em DESC')->fetchAll();
$orcamentosAprovados = banco()->query('SELECT o.id, o.codigo, o.local_obra, c.nome AS cliente FROM orcamentos o JOIN clientes c ON c.id = o.cliente_id LEFT JOIN obras_acompanhamento obra ON obra.orcamento_id = o.id WHERE o.status = "aprovado" AND obra.id IS NULL ORDER BY o.atualizado_em DESC')->fetchAll();
function esc(string $texto): string { return htmlspecialchars($texto, ENT_QUOTES, 'UTF-8'); }
function statusObra(string $status): string { return ['em_andamento' => 'Em andamento', 'pausada' => 'Pausada', 'concluida' => 'Concluída'][$status] ?? 'Atualização'; }
function acaoObra(string $status): string
{
    return ['em_andamento' => 'Registrar atualização', 'pausada' => 'Atualizar status', 'concluida' => 'Ver página do cliente'][$status] ?? 'Abrir obra';
}
?>
