  <section class="works-section" aria-labelledby="works-list-title"><div class="works-section-heading"><div><p class="eyebrow">Em execução</p><h2 id="works-list-title">Obras em andamento</h2></div><span><?= count($obras) ?></span></div><div class="works-list" aria-label="Obras em andamento">
    <?php foreach ($obras as $obra): $url = 'obra-cliente.php?acesso=' . urlencode($obra['token_acesso']); $codigoAcesso = trim((string) ($obra['codigo_acesso_exibicao'] ?? '')); $mensagem = 'Olá, ' . $obra['cliente_nome'] . "!\n\nUma nova atualização da sua obra foi publicada.\n\nO que foi feito: " . ($obra['ultimo_resumo'] ?: 'Confira a nova atualização na sua página privada.') . "\n\nAcompanhe por aqui: " . ((isset($_SERVER['HTTPS']) && $_SERVER['HTTPS'] !== 'off') ? 'https' : 'http') . '://' . ($_SERVER['HTTP_HOST'] ?? 'localhost') . rtrim(dirname($_SERVER['SCRIPT_NAME']), '/') . '/' . $url . ($codigoAcesso ? "\n\nCódigo de acesso: " . $codigoAcesso : ''); ?>
      <details class="work-card"><summary class="work-card-summary"><div class="work-card-top"><span class="work-status status-<?= esc($obra['status']) ?>"><?= esc(statusObra($obra['status'])) ?></span><span class="work-date"><small>Última atualização</small><time datetime="<?= esc(date('Y-m-d', strtotime($obra['atualizado_em']))) ?>"><?= date('d/m/Y', strtotime($obra['atualizado_em'])) ?></time></span></div><h2><?= esc($obra['titulo']) ?></h2><span class="work-summary-action"><?= esc(acaoObra($obra['status'])) ?> <b aria-hidden="true">›</b></span><p class="work-client"><strong><?= esc($obra['cliente_nome']) ?></strong><span><?= esc($obra['localidade'] ?: 'Local não informado') ?></span></p></summary><div class="work-card-content"><div class="work-next"><span class="work-next-mark" aria-hidden="true">→</span><div><small>Em seguida</small><strong><?= esc($obra['proxima_etapa'] ?: 'A confirmar') ?></strong></div></div><div class="work-card-actions"><a class="primary-action" href="atualizar-obra.php?id=<?= (int) $obra['id'] ?>"><span aria-hidden="true">+</span> Registrar atualização</a><?php if ($codigoAcesso): ?><a class="whatsapp-update" href="https://wa.me/?text=<?= rawurlencode($mensagem) ?>" target="_blank" rel="noopener"><img src="../assets/icons/whatsapp.svg" width="18" height="18" alt="">Avisar cliente no WhatsApp</a><?php endif; ?><div class="work-link-panel"><div><small>Link privado</small><strong><?= esc($codigoAcesso ? 'Código ' . $codigoAcesso : 'Sem código exibido') ?></strong></div><div class="work-secondary-actions"><a class="secondary-action" href="<?= esc($url) ?>" target="_blank" rel="noopener">Abrir página <span aria-hidden="true">↗</span></a><button class="secondary-action copy-link" type="button" data-link="<?= esc($url) ?>">Copiar link</button></div></div></div></div></details>
    <?php endforeach; ?>
  </div></section>
</main><?php $activeNav = 'obras'; require __DIR__ . '/app/nav-painel.php'; ?><dialog class="confirm-dialog create-work-dialog" data-create-work-dialog aria-labelledby="create-work-title"><div class="confirm-dialog-icon is-positive" aria-hidden="true">+</div><p class="eyebrow">Nova obra</p><h2 id="create-work-title">Criar obra agora?</h2><p>A obra será criada com link e código de acesso. Em seguida, você registrará a primeira atualização para o cliente.</p><div class="confirm-dialog-actions"><button class="secondary-action" type="button" data-create-work-cancel>Cancelar</button><button class="primary-action" type="button" data-create-work-confirm>Criar e atualizar</button></div></dialog><script src="scripts/obras.js"></script></body></html>


